    const J = LIVE.creatures.jelly;
    const lost = Math.min(p.mass * J.stingSpill, J.stingMaxSpill);
    p.mass = Math.max(1, p.mass - lost);
    p.radius = radiusFor(p.mass);
    p.boostLock = J.stingBoostLockSec;
    p.boostActive = false;
    p.stingCooldown = J.stingCooldownSec;
    spill(this.pool, this.rng, p.x, p.y, p.radius, lost, J.spillPieces);
