      const q = alive[i].player;
      const vh = viewHeightFor(q.mass);
      const halfDiag = hypot(vh * 0.5, vh) / 2;
      const keepRadius = halfDiag * LIVE.director.cullRing;
      const seeHalfW = vh * 0.89 * 1.15 + vh * 0.15;
      const seeHalfH = vh * 1.15 / 2 + vh * 0.15;
